IfThenElse:
IF o \in Object
          THEN  LET IdSetOf(x) == IF x \in Value
                                    THEN {} 
                                    ELSE IF x \in Id
                                           THEN {x}
                                           ELSE Range(x) \cap Id 
                IN  UNION {IdSetOf(o[fld]) : fld \in (DOMAIN o) \\ {"type"}}
          ELSE {}

IF x \in Value
                                    THEN {} 
                                    ELSE IF x \in Id
                                           THEN {x}
                                           ELSE Range(x) \cap Id

IF (o \in Object) /\ (o.type # "promise")
          THEN {i \in {o[x] : x \in DOMAIN o} : i \in Id}
          ELSE {}
